Here is the problem description:
<problem_description>
Firecrackers scare Nian the monster, but they're wayyyyy too noisy! Maybe fireworks make a nice complement.Little Tommy is watching a firework show. As circular shapes spread across the sky, a splendid view unfolds on the night of Lunar New Year's eve.A wonder strikes Tommy. How many regions are formed by the circles on the sky? We consider the sky as a flat plane. A region is a connected part of the plane with positive area, whose bound consists of parts of bounds of the circles and is a curve or several curves without self-intersections, and that does not contain any curve other than its boundaries. Note that exactly one of the regions extends infinitely.
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int testNum = 1;
            while (true) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                int n = Integer.parseInt(st.nextToken());
                int D = Integer.parseInt(st.nextToken());
                if (n == 0 && D == 0) break;

                pw.println("@" + testNum++);

                final double r = 1;
                Point pl = new Point(-D, 0);
                Point pr = new Point(D, 0);

                for (int i = 0; i < n; i++) {
                    st = new StringTokenizer(br.readLine());
                    int sl = Integer.parseInt(st.nextToken());
                    int sr = Integer.parseInt(st.nextToken());
                    double vl = sl / 180.0 * Math.PI * r;
                    double vr = sr / 180.0 * Math.PI * r;
                    int t = Integer.parseInt(st.nextToken());

                    if (sl == sr) {
                        Point v = pr.sub(pl).rotate(Math.PI / 2).norm().scale((vl + vr) * 0.5 * t);
                        pl = pl.add(v);
                        pr = pr.add(v);
                        continue;
                    }

                    double x = D * (vl + vr) / (vl - vr);
                    Point o = pl.add(pr).scale(0.5);
                    Point ox = o.add(pr.sub(o).norm().scale(x));

                    Point nl = pl.sub(ox);
                    Point nr = pr.sub(ox);
                    double wl = vl / nl.length();
                    double wr = vr / nr.length();

                    nl = nl.rotate(wl * t);
                    nr = nr.rotate(wr * t);

                    pl = nl.add(ox);
                    pr = nr.add(ox);
                }

                Point p = pl.add(pr).scale(0.5);
                pw.printf("%.10f\n", p.x);
                pw.printf("%.10f\n", p.y);
            }
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static class Point {
        double x, y;

        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        Point add(Point o) { return new Point(x + o.x, y + o.y); }
        Point sub(Point o) { return new Point(x - o.x, y - o.y); }

        Point rotate(double alpha) {
            double c = Math.cos(alpha), s = Math.sin(alpha);
            return new Point(x * c - y * s, x * s + y * c);
        }

        Point norm() {
            double len = length();
            return scale(1.0 / len);
        }

        Point scale(double f) { return new Point(f * x, f * y); }

        double length() { return Math.sqrt(x * x + y * y); }
    }
}
